SELECT * FROM mrp_daily_plan_override
WHERE batch_id=#{batchId}
  AND factory_code=#{factoryCode}
  AND root_material_code=#{rootMaterialCode}
  AND terminal_material_code=#{terminalMaterialCode}
  AND terminal_type=#{terminalType}
  AND supply_mode=#{supplyMode}
  AND path_group_key=#{pathGroupKey}
  AND schedule_date=#{scheduleDate}
LIMIT 1
